var data = msg.payload;
if (typeof data === 'string') { data = JSON.parse(data); }
data.received = new Date().toISOString();

var threshold = flow.get('tempThreshold');
if (threshold === undefined || threshold === null) {
    threshold = 30;
    flow.set('tempThreshold', threshold);
}

var suhu = Number(data.suhu);
var kelembaban = Number(data.kelembaban);
var isAlert = suhu > threshold;

data.threshold = threshold;
data.alert = isAlert;
flow.set('lastSensor', data);

var wsMsg = {
    payload: {
        type: 'sensor_update',
        threshold: threshold,
        data: data
    }
};

var ts = String(data.timestamp || data.received).replace(/\s+/g, '');
var rcv = String(data.received).replace(/\s+/g, '');
var dbArgs = {
    payload: 'insert ' + suhu + ' ' + kelembaban + ' ' + Number(threshold) + ' ' + (isAlert ? 1 : 0) + ' ' + ts + ' ' + rcv
};

var notifMsg = null;
if (isAlert) {
    var notif = {
        type: 'ALERT_SUHU',
        suhu: suhu,
        threshold: threshold,
        message: 'PERINGATAN: Suhu ' + suhu + ' C melewati batas ' + threshold + ' C!',
        timestamp: data.received
    };
    node.warn(notif.message);
    notifMsg = { payload: notif, topic: 'iot/notifikasi' };
}

return [wsMsg, dbArgs, notifMsg];

const VALID_KEY = 'iot-secret-2026';
const key = msg.req && msg.req.headers ? msg.req.headers['x-api-key'] : '';
if (key !== VALID_KEY) {
    msg.statusCode = 401;
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    msg.payload = {status: 'error', message: 'Unauthorized: X-API-Key tidak valid'};
    return [null, msg];
}
msg.payload = 'latest';
return [msg, null];

var threshold = flow.get('tempThreshold');
if (threshold === undefined || threshold === null) threshold = 30;
var row = JSON.parse(msg.payload);
msg.statusCode = 200;
msg.headers = {'Access-Control-Allow-Origin': '*'};
msg.payload = {
    status: 'success',
    threshold: threshold,
    data: row,
    server_time: new Date().toISOString()
};
return msg;

