msg.payload = 'history';
return [msg, null];

var rows = JSON.parse(msg.payload);
msg.statusCode = 200;
msg.headers = {'Access-Control-Allow-Origin': '*'};
msg.payload = {
    status: 'success',
    source: 'python-sqlite3',
    count: rows.length,
    data: rows
};
return msg;

