return [msg, null];

var body = msg.payload;
if (!body || !body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}
var mqttMsg = {payload: body, topic: 'iot/kontrol'};
node.send([null, mqttMsg]);

msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Perintah terkirim', sent: body};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, null];

const VALID_KEY = 'iot-secret-2026';
const key = msg.req && msg.req.headers ? msg.req.headers['x-api-key'] : '';
if (key !== VALID_KEY) {
    msg.statusCode = 401;
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    msg.payload = {status: 'error', message: 'Unauthorized: X-API-Key tidak valid'};
    return [null, msg];
}
return [msg, null];

var body = msg.payload;
var raw = body ? (body.threshold !== undefined ? body.threshold : body.max_suhu) : undefined;
var val = Number(raw);
if (raw === undefined || raw === '' || isNaN(val)) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'Field threshold wajib berupa angka'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}
flow.set('tempThreshold', val);
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diperbarui menjadi ' + val + ' C', threshold: val};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
